        heap = Arrays.copyOf(heap, heap.length * 2);
    }

    private void requireValidIndex(int i) {
        if (i < 0 || i >= size)
            throw new IndexOutOfBoundsException("Index " + i + " out of bounds for size " + size);
    }

    private void siftUp(int i) {
        while (i != 0 && compare(i, parent(i)) < 0) {
            swap(i, parent(i));
            i = parent(i);
        }
    }

