            int l = left(i);
            int r = right(i);
            int smallest = i;
            if (l < size && compare(l, smallest) < 0) smallest = l;
            if (r < size && compare(r, smallest) < 0) smallest = r;
            if (smallest == i) break;
            swap(i, smallest);
            i = smallest;
        }
    }

