        if (cmp < 0) heapify(i);
        else siftUp(i);
    }

    public boolean remove(T value) {
        for (int i = 0; i < size; i++) {
            if (comparator.compare(at(i), value) == 0) {
                removeAt(i);
                return true;
            }
        }
        return false;
